--
-- Table structure for table `approval_requests`
--

DROP TABLE IF EXISTS `approval_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `approval_requests` (
  `id` int NOT NULL AUTO_INCREMENT,
  `request_type` varchar(40) NOT NULL,
  `subject_id` int DEFAULT NULL,
  `subject_label` varchar(255) DEFAULT NULL,
  `payload` json DEFAULT NULL,
  `required_role` varchar(40) NOT NULL,
  `assigned_role` varchar(40) NOT NULL,
  `assigned_to` int DEFAULT NULL,
  `status` varchar(40) NOT NULL,
  `priority` varchar(20) NOT NULL,
  `flags` json DEFAULT NULL,
  `audit_trail` json DEFAULT NULL,
  `escalation_level` int NOT NULL,
  `max_escalation_level` int NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `due_at` datetime DEFAULT NULL,
  `auto_approve_at` datetime DEFAULT NULL,
  `escalated_at` datetime DEFAULT NULL,
  `decided_at` datetime DEFAULT NULL,
  `decided_by` varchar(120) DEFAULT NULL,
  `decision_note` text,
  PRIMARY KEY (`id`),
