INSERT INTO `approval_requests` VALUES (157,'ad_inquiry',83,'Ad inquiry: Eng.Md.Mahi Uddin (Dazzelsoft)','{\"name\": \"Eng.Md.Mahi Uddin\", \"email\": \"motin.mmk.jr@gmail.com\", \"phone\": \"01715994956\", \"company\": \"Dazzelsoft\", \"message\": \"add\", \"draft_body\": \"প্রিয় Eng.Md.Mahi Uddin,\\n\\nআপনার বিজ্ঞাপন সংক্রান্ত অনুসন্ধানের জন্য ধন্যবাদ। দি ডেইলি এআই আলো-তে\\nআপনার ব্র্যান্ডকে আমাদের পাঠকদের সামনে তুলে ধরার সুযোগ রয়েছে।\\n\\nআমাদের রেট কার্ড / Our rate card:\\n• হোমপেজ ব্যানার (Homepage Banner): ৳ ১৫,০০০ / মাস\\n• স্পনসরড কন্টেন্ট (Sponsored Article): ৳ ১২,০০০ / প্রতি প্রবন্ধ\\n• নিউজলেটার প্লেসমেন্ট (Newsletter): ৳ ৮,০০০ / প্রতি সংখ্যা\\n• সোশ্যাল ক্রস-পোস্ট (Social Boost): ৳ ৫,০০০ / ক্যাম্পেইন\\n\\nআগ্রহী প্যাকেজ: sponsored_article\\nবাজেট নোট: 300\\n\\nবিস্তারিত আলোচনার জন্য আমাদের বিজ্ঞাপন বিভাগে উত্তর দিন। আমরা ২৪ ঘণ্টার মধ্যে\\nযোগাযোগ করব।\\n\\nধন্যবাদ,\\nবিজ্ঞাপন বিভাগ, দি ডেইলি এআই আলো (The Daily AI Alo)\\n(প্রকাশক: The Daily AI Alo Media & Tech Labs)\", \"budget_note\": \"300\", \"draft_subject\": \"বিজ্ঞাপন সম্পর্কে / Re: Your advertising inquiry — The Daily AI Alo\", \"package_interest\": \"sponsored_article\", \"draft_generated_by\": \"template\"}','ad_manager','ad_manager',NULL,'pending','normal','[]','[{\"at\": \"2026-09-27T03:06:51.011213\", \"actor\": \"ai_agent\", \"event\": \"INTAKE\", \"message\": \"Routed to ad_manager (flags: none)\"}]',0,1,'2026-09-27 03:06:51','2026-09-27 09:06:51',NULL,NULL,NULL,NULL,NULL);
