--
-- Table structure for table `social_broadcast_logs`
--

DROP TABLE IF EXISTS `social_broadcast_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `social_broadcast_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `article_id` int DEFAULT NULL,
  `channel_id` int DEFAULT NULL,
  `platform` varchar(50) NOT NULL,
  `target_account` varchar(150) NOT NULL,
  `post_payload` json DEFAULT NULL,
  `external_post_id` varchar(255) DEFAULT NULL,
  `dispatch_status` varchar(50) DEFAULT NULL,
  `response_data` json DEFAULT NULL,
  `error_message` text,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_social_broadcast_logs_created_at` (`created_at`),
  KEY `ix_social_broadcast_logs_channel_id` (`channel_id`),
  KEY `ix_social_broadcast_logs_platform` (`platform`),
  KEY `ix_social_broadcast_logs_article_id` (`article_id`),
  KEY `ix_social_broadcast_logs_dispatch_status` (`dispatch_status`),
  CONSTRAINT `social_broadcast_logs_ibfk_1` FOREIGN KEY (`article_id`) REFERENCES `articles` (`id`) ON DELETE SET NULL,
  CONSTRAINT `social_broadcast_logs_ibfk_2` FOREIGN KEY (`channel_id`) REFERENCES `social_channel_configs` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3445 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

