DROP TABLE IF EXISTS `social_channel_configs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `social_channel_configs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `platform` varchar(50) NOT NULL,
  `account_name` varchar(150) NOT NULL,
  `page_id_or_channel_id` varchar(255) NOT NULL,
  `app_id` varchar(255) DEFAULT NULL,
  `app_secret` varchar(255) DEFAULT NULL,
  `access_token` text,
  `webhook_verify_token` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  `is_primary` tinyint(1) DEFAULT NULL,
  `status` varchar(50) DEFAULT NULL,
  `failover_account_id` int DEFAULT NULL,
  `total_posts_dispatched` int DEFAULT NULL,
  `last_post_at` datetime DEFAULT NULL,
  `last_error_message` text,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `failover_account_id` (`failover_account_id`),
  KEY `ix_social_channel_configs_is_active` (`is_active`),
  KEY `ix_social_channel_configs_status` (`status`),
  KEY `ix_social_channel_configs_platform` (`platform`),
  CONSTRAINT `social_channel_configs_ibfk_1` FOREIGN KEY (`failover_account_id`) REFERENCES `social_channel_configs` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=173 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

